-- PKG_DMF0014 — 클라우드 현재 상태 점검 (SCM_MGR · 조회 전용 · 변경 없음)
-- VERDICT: PRE=사내 적용 전과 동일 → 해당 파일 적용 / POST=이미 적용 → SKIP / ABSENT=없음 / DIFF=클라우드 본문이 다름 → 전체교체 금지·결과 공유
SET PAGESIZE 200 LINESIZE 300
COLUMN OBJ FORMAT A48
COLUMN VERDICT FORMAT A60

-- [A] 교체 대상 객체
SELECT 'PKG_DMF0014' OBJ, 'PACKAGE' TYP, '10_SPEC.sql' FILE_NM,
       (SELECT STATUS FROM USER_OBJECTS WHERE OBJECT_NAME = 'PKG_DMF0014' AND OBJECT_TYPE = 'PACKAGE') CLOUD_STATUS,
       CASE WHEN NOT EXISTS (SELECT 1 FROM USER_OBJECTS WHERE OBJECT_NAME = 'PKG_DMF0014' AND OBJECT_TYPE = 'PACKAGE') THEN 'ABSENT → ⚠ 기존 객체 부재: 선행 이관 필요'
            WHEN H.S = 202578492769 THEN 'POST → 이미 적용됨(SKIP)'
            WHEN H.S = 183348396479 THEN 'PRE → 적용 대상'
            ELSE 'DIFF → ⚠ 클라우드 본문이 사내와 다름: 전체교체 금지·결과 공유' END VERDICT
  FROM (SELECT SUM(ORA_HASH(RTRIM(TEXT, CHR(10)||CHR(13)||CHR(32)||CHR(9)))) S FROM USER_SOURCE WHERE NAME = 'PKG_DMF0014' AND TYPE = 'PACKAGE' AND LINE > 1) H;
SELECT 'PKG_DMF0014' OBJ, 'PACKAGE BODY' TYP, '11_BODY.sql' FILE_NM,
       (SELECT STATUS FROM USER_OBJECTS WHERE OBJECT_NAME = 'PKG_DMF0014' AND OBJECT_TYPE = 'PACKAGE BODY') CLOUD_STATUS,
       CASE WHEN NOT EXISTS (SELECT 1 FROM USER_OBJECTS WHERE OBJECT_NAME = 'PKG_DMF0014' AND OBJECT_TYPE = 'PACKAGE BODY') THEN 'ABSENT → ⚠ 기존 객체 부재: 선행 이관 필요'
            WHEN H.S = 24197901487929 THEN 'POST → 이미 적용됨(SKIP)'
            WHEN H.S = 15704733835998 THEN 'PRE → 적용 대상'
            ELSE 'DIFF → ⚠ 클라우드 본문이 사내와 다름: 전체교체 금지·결과 공유' END VERDICT
  FROM (SELECT SUM(ORA_HASH(RTRIM(TEXT, CHR(10)||CHR(13)||CHR(32)||CHR(9)))) S FROM USER_SOURCE WHERE NAME = 'PKG_DMF0014' AND TYPE = 'PACKAGE BODY' AND LINE > 1) H;

-- [B] DROP 대상 standalone — 멤버 본문 원천. DIFF 면 클라우드에만 있는 수정 → 멤버에 반영 필요(결과 공유)
SELECT 'PR_DM_CUST_ITEM_MAPPING' OBJ, (SELECT STATUS FROM USER_OBJECTS WHERE OBJECT_NAME = 'PR_DM_CUST_ITEM_MAPPING' AND OBJECT_TYPE = 'PROCEDURE') CLOUD_STATUS,
       CASE WHEN H.S IS NULL THEN 'ABSENT(이미 삭제됐거나 미이관)' WHEN H.S IN (1322121405593, 1322121405593) THEN 'SAME(사내 원천과 동일)' ELSE 'DIFF → ⚠ 결과 공유' END VERDICT
  FROM (SELECT SUM(ORA_HASH(RTRIM(TEXT, CHR(10)||CHR(13)||CHR(32)||CHR(9)))) S FROM USER_SOURCE WHERE NAME = 'PR_DM_CUST_ITEM_MAPPING' AND TYPE = 'PROCEDURE' AND LINE > 1) H;
SELECT 'PR_DM_PLN_CUST_FCST_TO_MKT_FCST' OBJ, (SELECT STATUS FROM USER_OBJECTS WHERE OBJECT_NAME = 'PR_DM_PLN_CUST_FCST_TO_MKT_FCST' AND OBJECT_TYPE = 'PROCEDURE') CLOUD_STATUS,
       CASE WHEN H.S IS NULL THEN 'ABSENT(이미 삭제됐거나 미이관)' WHEN H.S IN (4104092414858, 4104092414858) THEN 'SAME(사내 원천과 동일)' ELSE 'DIFF → ⚠ 결과 공유' END VERDICT
  FROM (SELECT SUM(ORA_HASH(RTRIM(TEXT, CHR(10)||CHR(13)||CHR(32)||CHR(9)))) S FROM USER_SOURCE WHERE NAME = 'PR_DM_PLN_CUST_FCST_TO_MKT_FCST' AND TYPE = 'PROCEDURE' AND LINE > 1) H;
SELECT 'PR_DM_PLN_CUST_FCST_TO_MKT_FCST_40' OBJ, (SELECT STATUS FROM USER_OBJECTS WHERE OBJECT_NAME = 'PR_DM_PLN_CUST_FCST_TO_MKT_FCST_40' AND OBJECT_TYPE = 'PROCEDURE') CLOUD_STATUS,
       CASE WHEN H.S IS NULL THEN 'ABSENT(이미 삭제됐거나 미이관)' WHEN H.S IN (3048497736699, 3048497736699) THEN 'SAME(사내 원천과 동일)' ELSE 'DIFF → ⚠ 결과 공유' END VERDICT
  FROM (SELECT SUM(ORA_HASH(RTRIM(TEXT, CHR(10)||CHR(13)||CHR(32)||CHR(9)))) S FROM USER_SOURCE WHERE NAME = 'PR_DM_PLN_CUST_FCST_TO_MKT_FCST_40' AND TYPE = 'PROCEDURE' AND LINE > 1) H;

-- [C] PKG_DMF0014 BODY 의존 객체 — 행이 나오면 MISSING (컴파일 실패 조건)
SELECT COLUMN_VALUE MISSING FROM TABLE(SYS.ODCIVARCHAR2LIST('DM_CUST_ITEM_MAPPING_DTL_H', 'DM_CUST_ITEM_MAPPING_DTL_N', 'DM_CUST_ITEM_MAPPING_M', 'DM_DNM_EDI_CALLOFF_ITEM', 'DM_MST_BUCKET_CONVERSION', 'DM_MST_CUSTOMER_FCST', 'DM_MST_CUSTOMER_MODEL', 'DM_PLN_CUSTOMER_PSI', 'DM_PLN_CUSTOMER_PSI_H', 'DM_PLN_MKT_FCST', 'FN_NEXT_DAY', 'FN_SCM_GET_WHERE_SQL', 'GT_DCIM_DM_CUST_ITEM_MAPPING_D', 'GT_DCIM_DM_DNM_EDI_CALLOFF_ITE', 'GT_DPCF_CALENDAR_DM_PLN_CUSTOM', 'GT_DPCF_CALENDAR_DM_PLN_CUSTOMER_PSI', 'GT_DPCF_CUST_FCST_DIVISION', 'GT_DPCF_DM_CUST_ITEM_MAPPING_D', 'GT_DPCF_DM_CUST_ITEM_MAPPING_DTL_N', 'GT_DPCF_DM_PLN_CUSTOMER_PSI', 'GT_DPCF_DM_PLN_CUSTOMER_PSI_2', 'GT_DPCF_MIN_MAX_PSI', 'GT_DPCF_MIN_MAX_PSI_2', 'GT_DPCF_PSI_GROUP_COUNT', 'GT_DPCF_PSI_GROUP_COUNT_2', 'GT_DPCF_RESULTS', 'GT_DPCF_RESULTS_2', 'GT_DPCF_T2_DM_PLN_CUSTOMER_PSI', 'GT_DPCF_T3_DM_PLN_CUSTOMER_PSI', 'GT_DPCF_TEMP2_DM_PLN_CUSTOMER', 'GT_DPCF_TEMP3_DM_PLN_CUSTOMER', 'GT_DPCF_TMP_SITE_CUSTOMER_MAP', 'GT_DPCF_TMP_SITE_CUSTOMER_MAP_2', 'GT_SCFU_RESULTS', 'PR_DM_PLN_MKT_FCST_MAKE_CUST_FCST', 'PR_DM_SYS_LOG_BATCH', 'PR_SCM_SYS_LOG_BATCH', 'SCM_ADM_EXCEL_COLUMNS', 'SCM_ADM_EXCEL_UPLOAD', 'SCM_ADM_LOOKUP_MASTER_DETAIL', 'SCM_MST_DIVISION', 'SCM_MST_ITEM_SN', 'SCM_MST_SITE', 'SCM_MST_SITE_ITEM', 'SCM_SYS_CALENDAR_M', 'SEQ1_DM_PLN_CUSTOMER_PSI_H')) WHERE COLUMN_VALUE NOT IN (SELECT OBJECT_NAME FROM USER_OBJECTS);

-- [E] 앱계정
SELECT GRANTEE, TABLE_NAME, PRIVILEGE FROM USER_TAB_PRIVS WHERE GRANTEE = 'SCMP_APP' AND TABLE_NAME = 'PKG_DMF0014';
SELECT OWNER, SYNONYM_NAME FROM ALL_SYNONYMS WHERE OWNER = 'SCMP_APP' AND SYNONYM_NAME = 'PKG_DMF0014';
